const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry (Shanghai) and date
  var shanghai = ee.Geometry.Polygon(
    [[[121.0, 31.0],
      [121.0, 31.5],
      [122.0, 31.5],
      [122.0, 31.0]]], null, false);

  var date = '2013-08-07';
  var startDate = ee.Date(date);
  var endDate = startDate.advance(1, 'day');

  // Function to process MODIS LST (Terra or Aqua)
  function processMODIS(collectionName, description) {
    var col = ee.ImageCollection(collectionName)
                .filterBounds(shanghai)
                .filterDate(startDate, endDate);
    var size = col.size().getInfo();
    print(description + ' Images: ' + size);
    if (size === 0) {
      return null;
    }
    var img = col.first();
    // Quality mask: bits 0-1 of QC_Day: 00 or 01 are good
    var qc = img.select('QC_Day');
    var mask = qc.bitwiseAnd(3).lte(1);
    var lst = img.select('LST_Day_1km').updateMask(mask);
    // Convert Kelvin to Celsius: scale 0.02, then -273.15
    var lstC = lst.multiply(0.02).subtract(273.15);
    return lstC;
  }

  // Function to process Landsat 8 LST
  function processLandsat8() {
    var col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterBounds(shanghai)
                .filterDate(startDate, endDate);
    var size = col.size().getInfo();
    print('Landsat 8 Images: ' + size);
    if (size === 0) {
      return null;
    }
    var img = col.first();
    // Cloud mask using QA_PIXEL: bits 3 and 4 are cloud and cloud shadow
    var qa = img.select('QA_PIXEL');
    var cloudMask = qa.bitwiseAnd(1<<3).eq(0).and(qa.bitwiseAnd(1<<4).eq(0));
    var lst = img.select('ST_B10').updateMask(cloudMask);
    // Convert to Celsius: ST_B10 * 0.00341802 + 149.0 gives Kelvin, then -273.15
    var lstK = lst.multiply(0.00341802).add(149.0);
    var lstC = lstK.subtract(273.15);
    return lstC;
  }

  // Try data sources in order
  var lstC = null;
  var source = '';

  // Try MODIS Terra
  lstC = processMODIS('MODIS/061/MOD11A1', 'MODIS Terra');
  if (lstC) {
    source = 'MODIS Terra';
  } else {
    // Try MODIS Aqua
    lstC = processMODIS('MODIS/061/MYD11A1', 'MODIS Aqua');
    if (lstC) {
      source = 'MODIS Aqua';
    } else {
      // Try Landsat 8
      lstC = processLandsat8();
      if (lstC) {
        source = 'Landsat 8';
      } else {
        print('No data found for any source.');
        print('<answer>C1</answer>');
        return;
      }
    }
  }

  print('Using source: ' + source);

  // Compute mean temperature and valid pixel count
  var stats = lstC.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  });

  var mean = stats.get('LST_Day_1km_mean');  // For MODIS
  if (mean === undefined) {
    mean = stats.get('ST_B10_mean');  // For Landsat
  }
  var count = stats.get('LST_Day_1km_count') || stats.get('ST_B10_count');

  mean = mean.getInfo();
  count = count.getInfo();

  print('Valid pixel count: ' + count);
  print('Mean LST (°C): ' + mean.toFixed(2));

  // Check for no valid pixels
  if (count === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // Validate result: not NaN and within plausible range
  if (mean === null || isNaN(mean) || mean < -50 || mean > 100) {
    print('<answer>C3</answer>');
    return;
  }

  // Final comparison
  if (mean > 39) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
